#!/usr/bin/env python3
"""Configures the Android project generated by `flutter create`.

Run from the repository root after `flutter create --platforms=android .`.
Idempotent: safe to run more than once.

* App label, launcher icons, large heap
* Permissions: CAMERA (Pro camera), USE_BIOMETRIC (app lock / vault)
* Release builds: INTERNET permission removed (offline-by-design privacy)
* MainActivity -> FlutterFragmentActivity (required by local_auth)
* minSdk 24, ML Kit Devanagari OCR model, R8 minification disabled
"""
import glob
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ANDROID = os.path.join(ROOT, 'android')
APP = os.path.join(ANDROID, 'app')


def read(p):
    with open(p, encoding='utf-8') as f:
        return f.read()


def write(p, s):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f:
        f.write(s)


def manifest():
    p = os.path.join(APP, 'src', 'main', 'AndroidManifest.xml')
    s = read(p)
    if 'xmlns:tools' not in s:
        s = s.replace('<manifest xmlns:android="http://schemas.android.com/apk/res/android"',
                      '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n    xmlns:tools="http://schemas.android.com/tools"', 1)
    if 'android.permission.CAMERA' not in s:
        perms = (
            '    <uses-permission android:name="android.permission.CAMERA" />\n'
            '    <uses-permission android:name="android.permission.USE_BIOMETRIC" />\n'
            '    <uses-feature android:name="android.hardware.camera" android:required="false" />\n'
            '    <uses-feature android:name="android.hardware.camera.autofocus" android:required="false" />\n'
        )
        s = s.replace('    <application', perms + '    <application', 1)
    s = re.sub(r'android:label="[^"]*"', 'android:label="ScanPro Studio"', s, count=1)
    if 'android:largeHeap' not in s:
        s = s.replace('<application', '<application\n        android:largeHeap="true"', 1)
    if 'android.media.action.IMAGE_CAPTURE' not in s:
        q = ('    <queries>\n'
             '        <intent>\n'
             '            <action android:name="android.media.action.IMAGE_CAPTURE" />\n'
             '        </intent>\n'
             '    </queries>\n')
        idx = s.rfind('</manifest>')
        s = s[:idx] + q + s[idx:]
    write(p, s)

    # Release-only manifest: remove INTERNET even if a library requests it.
    rel = os.path.join(APP, 'src', 'release', 'AndroidManifest.xml')
    write(rel, (
        '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n'
        '    xmlns:tools="http://schemas.android.com/tools">\n'
        '    <!-- Privacy by design: the release app never needs network access. -->\n'
        '    <uses-permission android:name="android.permission.INTERNET" tools:node="remove" />\n'
        '    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" tools:node="remove" />\n'
        '</manifest>\n'))


def main_activity():
    files = glob.glob(os.path.join(APP, 'src', 'main', 'kotlin', '**', 'MainActivity.kt'), recursive=True)
    files += glob.glob(os.path.join(APP, 'src', 'main', 'java', '**', 'MainActivity.java'), recursive=True)
    if not files:
        print('MainActivity not found', file=sys.stderr)
        sys.exit(1)
    for p in files:
        s = read(p)
        pkg = re.search(r'^package\s+([\w.]+)', s, re.M).group(1)
        if p.endswith('.kt'):
            write(p, f'package {pkg}\n\nimport io.flutter.embedding.android.FlutterFragmentActivity\n\n'
                     'class MainActivity : FlutterFragmentActivity()\n')
        else:
            write(p, f'package {pkg};\n\nimport io.flutter.embedding.android.FlutterFragmentActivity;\n\n'
                     'public class MainActivity extends FlutterFragmentActivity {}\n')


KTS_BLOCK = '''
// --- ScanPro Studio configuration (tool/configure_android.py) ---
android {
    buildTypes {
        getByName("release") {
            isMinifyEnabled = false
            isShrinkResources = false
        }
    }
}

dependencies {
    // Bundled on-device Hindi/Devanagari OCR model for google_mlkit_text_recognition.
    implementation("com.google.mlkit:text-recognition-devanagari:16.0.0")
}
'''

GROOVY_BLOCK = '''
// --- ScanPro Studio configuration (tool/configure_android.py) ---
android {
    buildTypes {
        release {
            minifyEnabled false
            shrinkResources false
        }
    }
}

dependencies {
    // Bundled on-device Hindi/Devanagari OCR model for google_mlkit_text_recognition.
    implementation "com.google.mlkit:text-recognition-devanagari:16.0.0"
}
'''


ROOT_KTS_BLOCK = '''
// --- ScanPro Studio: plugin compileSdk (tool/configure_android.py) ---
// flutter_plugin_android_lifecycle requires dependants to compile against
// API 36+, but some plugins (e.g. file_picker 8.x) still pin 34.
subprojects {
    if (project.name != "app") {
        val raiseCompileSdk = {
            extensions.findByName("android")?.withGroovyBuilder {
                val current = "getCompileSdk"() as Int?
                if (current == null || current < 36) "setCompileSdk"(36)
            }
        }
        if (state.executed) raiseCompileSdk() else afterEvaluate { raiseCompileSdk() }
    }
}
'''

ROOT_GROOVY_BLOCK = '''
// --- ScanPro Studio: plugin compileSdk (tool/configure_android.py) ---
// flutter_plugin_android_lifecycle requires dependants to compile against
// API 36+, but some plugins (e.g. file_picker 8.x) still pin 34.
subprojects {
    if (project.name != "app") {
        def raiseCompileSdk = {
            def android = project.extensions.findByName("android")
            if (android != null && (android.compileSdk == null || android.compileSdk < 36)) {
                android.compileSdk = 36
            }
        }
        if (project.state.executed) raiseCompileSdk() else project.afterEvaluate { raiseCompileSdk() }
    }
}
'''

EVAL_DEPENDS = re.compile(r'^subprojects\s*\{\s*project\.evaluationDependsOn\(\s*["\']:app["\']\s*\)', re.M)


def root_gradle():
    for name, block in (('build.gradle.kts', ROOT_KTS_BLOCK), ('build.gradle', ROOT_GROOVY_BLOCK)):
        p = os.path.join(ANDROID, name)
        if not os.path.exists(p):
            continue
        s = read(p)
        if 'ScanPro Studio: plugin compileSdk' in s:
            return
        # Register before evaluationDependsOn(":app") so the hook is in place
        # before plugin projects are evaluated.
        m = EVAL_DEPENDS.search(s)
        s = s[:m.start()] + block.lstrip('\n') + '\n' + s[m.start():] if m else s + block
        write(p, s)
        return
    print('root build.gradle not found', file=sys.stderr)
    sys.exit(1)


def gradle():
    root_gradle()
    kts = os.path.join(APP, 'build.gradle.kts')
    groovy = os.path.join(APP, 'build.gradle')
    if os.path.exists(kts):
        s = read(kts)
        s = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', s)
        s = re.sub(r'minSdk\s*=\s*\d+', 'minSdk = 24', s)
        if 'ScanPro Studio configuration' not in s:
            s += KTS_BLOCK
        write(kts, s)
    elif os.path.exists(groovy):
        s = read(groovy)
        s = re.sub(r'minSdkVersion\s+flutter\.minSdkVersion', 'minSdkVersion 24', s)
        s = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', s)
        if 'ScanPro Studio configuration' not in s:
            s += GROOVY_BLOCK
        write(groovy, s)
    else:
        print('app build.gradle not found', file=sys.stderr)
        sys.exit(1)

    props = os.path.join(ANDROID, 'gradle.properties')
    s = read(props) if os.path.exists(props) else ''
    s = re.sub(r'^org\.gradle\.jvmargs=.*$', '', s, flags=re.M)
    s = 'org.gradle.jvmargs=-Xmx4G -XX:MaxMetaspaceSize=1G -XX:+HeapDumpOnOutOfMemoryError\n' + s.strip() + '\n'
    if 'android.useAndroidX' not in s:
        s += 'android.useAndroidX=true\n'
    write(props, s)


def icons():
    src = os.path.join(ROOT, 'tool', 'icons')
    res = os.path.join(APP, 'src', 'main', 'res')
    for d in glob.glob(os.path.join(src, 'mipmap-*')):
        name = os.path.basename(d)
        os.makedirs(os.path.join(res, name), exist_ok=True)
        for f in os.listdir(d):
            shutil.copy(os.path.join(d, f), os.path.join(res, name, f))


if __name__ == '__main__':
    if not os.path.isdir(APP):
        print('Run `flutter create --platforms=android .` first', file=sys.stderr)
        sys.exit(1)
    manifest()
    main_activity()
    gradle()
    icons()
    print('Android project configured.')
